<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kelola Siswa {{ $class }} — FRExam</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap" rel="stylesheet"><style>:root{font-family:Inter,sans-serif;color:#1f2937}*{box-sizing:border-box}body{margin:0;min-height:100vh;padding:30px 20px;background:#f4f7fb}.wrap{max-width:1150px;margin:auto}.back{display:inline-block;padding:10px 13px;background:#fff;border-radius:10px;color:#23395d;text-decoration:none;font-weight:800}.hero{margin:18px 0;padding:27px 30px;border-radius:21px;background:linear-gradient(115deg,#23395d,#365d92);color:#fff}.hero h1{margin:0 0 7px}.hero p{margin:0;color:#e7effa}.grid{display:grid;grid-template-columns:320px 1fr;gap:16px}.card{padding:20px;background:#fffd;border:1px solid #fff;border-radius:17px;box-shadow:0 10px 23px #23395d12;overflow:auto}.field{display:grid;gap:6px;margin:11px 0}.field label{font-size:11px;font-weight:800;color:#475569}input{padding:10px;border:1px solid #cbd5e1;border-radius:9px;font:inherit}.button{border:0;border-radius:9px;padding:10px 12px;background:#23395d;color:#fff;font-weight:800;cursor:pointer}.red{background:#b91c1c}table{width:100%;border-collapse:collapse;min-width:520px}th,td{padding:12px 8px;text-align:left;border-bottom:1px solid #e5edf5}th{font-size:11px;color:#64748b;text-transform:uppercase}.edit{color:#23395d;font-weight:800;text-decoration:none;font-size:12px}.actions{display:flex;gap:6px}.empty{text-align:center;color:#64748b;padding:32px!important}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><a class="back" href="{{ route('admin.teacher.classes',$teacher) }}">← Kelas Diampu Guru</a><section class="hero"><h1>Kelola Siswa Kelas {{ $class }}</h1><p>Guru: {{ $teacher->name }} · Admin dapat menambah, mengubah, atau menghapus data siswa.</p></section><section class="grid"><section class="card"><h2>Tambah Siswa</h2><form method="post" action="{{ route('admin.users.store') }}">@csrf<input type="hidden" name="role" value="student"><div class="field"><label>NAMA SISWA</label><input name="name" required></div><div class="field"><label>NISN</label><input name="nisn" required></div><div class="field"><label>KELAS</label><input name="class_name" value="{{ $class }}" readonly></div><div class="field"><label>PASSWORD</label><input type="password" name="password" required></div><div class="field"><label>KONFIRMASI PASSWORD</label><input type="password" name="password_confirmation" required></div><button class="button">+ Tambah Siswa</button></form></section><section class="card"><h2>Daftar Siswa</h2><table><thead><tr><th>No.</th><th>Nama</th><th>NISN</th><th>Status</th><th>Aksi</th></tr></thead><tbody>@forelse($students as $index=>$student)<tr><td>{{ $index+1 }}</td><td><strong>{{ $student->name }}</strong></td><td>{{ $student->nisn }}</td><td>{{ $student->is_active?'Aktif':'Nonaktif' }}</td><td><div class="actions"><a class="edit" href="{{ route('admin.users.edit',$student) }}">Ubah</a><form method="post" action="{{ route('admin.users.destroy',$student) }}" onsubmit="return confirm('Hapus siswa ini?')">@csrf @method('DELETE')<button class="button red">Hapus</button></form></div></td></tr>@empty<tr><td colspan="5" class="empty">Belum ada siswa di kelas ini.</td></tr>@endforelse</tbody></table></section></section></main></body></html>
